statement:
`board` is an `m x n` crossword grid. Every cell holds `'#'` (a blocked square), `' '` (an empty square) or a lowercase letter left there by an earlier answer. Decide whether `word` fits into the grid along one row or one column, read in any of the four directions (left to right, right to left, top to bottom or bottom to top), with all of these holding:

- none of its letters lands on a `'#'`;
- each letter lands either on an empty square or on a square that already shows that same letter;
- along that line, the square just before the first letter and the square just after the last letter are each `'#'` or outside the grid (an empty square or a letter there is not allowed).

Return `true` if such a placement exists and `false` otherwise.

validator:
function validate([board, word]) {
  if (!Array.isArray(board) || board.length < 1 || !Array.isArray(board[0]) || board[0].length < 1) return 'board needs at least one cell.';
  const cols = board[0].length;
  if (board.length * cols > 200000) return 'board has at most 2 * 10^5 cells.';
  for (const row of board) {
    if (!Array.isArray(row) || row.length !== cols) return 'Every row of board has the same length.';
    if (row.some(ch => ch !== ' ' && ch !== '#' && !/^[a-z]$/.test(ch))) return "Cells are ' ', '#' or a lowercase letter.";
  }
  if (typeof word !== 'string' || !/^[a-z]+$/.test(word)) return 'word is a non-empty string of lowercase letters.';
  if (word.length > Math.max(board.length, cols)) return 'word is at most max(m, n) letters long.';
  return null;
}

