function placeWordInCrossword(board, word) {
  const rows = board.length;
  const cols = board[0].length;
  const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  const isOpen = (row, col) => row >= 0 && row < rows && col >= 0 && col < cols && board[row][col] !== '#';

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      for (const [dr, dc] of directions) {
        if (isOpen(row - dr, col - dc)) {
          continue;
        }
        let i = 0;
        while (i < word.length && isOpen(row + i * dr, col + i * dc)) {
          const cell = board[row + i * dr][col + i * dc];
          if (cell !== ' ' && cell !== word[i]) {
            break;
          }
          i++;
        }
        if (i === word.length && !isOpen(row + i * dr, col + i * dc)) {
          return true;
        }
      }
    }
  }
  return false;
}

