function placeWordInCrossword(board, word) {
  // Collect every maximal run of non-'#' squares in each row and column, then try the word both ways.
  const lines = board.map(r => r.join(''));
  for (let c = 0; c < board[0].length; c++) lines.push(board.map(r => r[c]).join(''));
  const reversed = word.split('').reverse().join('');
  const fits = (slot, w) => slot.length === w.length && [...slot].every((ch, i) => ch === ' ' || ch === w[i]);
  for (const line of lines) {
    for (const slot of line.split('#')) {
      if (fits(slot, word) || fits(slot, reversed)) return true;
    }
  }
  return false;
}

