function generate(rand, size) {
  const large = size === 'large';
  const rows = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const cols = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const letters = large ? 'abcdef' : 'ab';
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const blocked = large ? 0.2 : rand() * 0.5;
  const board = Array.from({ length: rows }, () => Array.from({ length: cols }, () => {
    const roll = rand();
    return roll < blocked ? '#' : roll < blocked + (1 - blocked) * (large ? 0.3 : 0.6) ? ' ' : pick();
  }));
  const maxLength = Math.max(rows, cols);
  const length = large ? 5 + Math.floor(rand() * 10) : 1 + Math.floor(rand() * maxLength);
  let word = '';
  for (let i = 0; i < length; i++) word += pick();
  // Often plant the word (or its reverse) in a slot, sometimes with one wrong letter, so both answers occur.
  if (rand() < 0.6) {
    const horizontal = length <= cols && (length > rows || rand() < 0.5);
    const span = horizontal ? cols : rows;
    const start = Math.floor(rand() * (span - length + 1));
    const fixed = Math.floor(rand() * (horizontal ? rows : cols));
    const text = rand() < 0.5 ? word : word.split('').reverse().join('');
    const spoil = rand() < 0.4 ? Math.floor(rand() * length) : -1;
    const put = (k, ch) => { if (horizontal) board[fixed][k] = ch; else board[k][fixed] = ch; };
    for (let i = 0; i < length; i++) put(start + i, i === spoil ? '#' : rand() < 0.5 ? ' ' : text[i]);
    if (start > 0) put(start - 1, '#');
    if (start + length < span) put(start + length, '#');
  }
  return [board, word];
}
